/* Authoring layer: arbitrary pose keys, camera keys, branding and practical lights. */
let chessMotionAPI=null,motionObject='b-knight-6',motionKey=0,cameraKey=0,logoObject='w-bishop-2';
import('./chess-motion.js?v=depot-v17').then(api=>{chessMotionAPI=api;if(activeEffect==='chess')renderChessDirector()});
function chessSeconds(){return Math.max(0,t*settings.duration-phaseTimes().chess)}
function seekChess(seconds){playing=false;t=(phaseTimes().chess+Math.max(0,Math.min(fx.chessDuration,seconds)))/settings.duration;document.querySelector('#play').textContent='▶';base._renderKey=''}
function homePose(id){const o=chessEngine?.objects.get(id),saved=fx.chessObjects?.[id];return saved?{...structuredClone(saved),rotation:saved.rotation.map(v=>v*180/Math.PI),visible:true}:{position:[...(o?.userData.home||[0,0,0])],rotation:[0,0,0],scale:[1,1,1],visible:true}}
function trackFor(id,edit=false){let tr=fx.chessTracks?.[id]||chessMotionAPI?.defaultTracks(fx)[id]||{enabled:true,keys:[{time:0,...homePose(id),ease:'smooth'}]};if(edit){fx.chessTracks||={};if(!fx.chessTracks[id])fx.chessTracks[id]=structuredClone(tr);tr=fx.chessTracks[id]}return tr}
function currentObjectPose(id){const o=chessEngine?.objects.get(id);return o?{position:o.position.toArray(),rotation:o.rotation.toArray().slice(0,3).map(v=>v*180/Math.PI),scale:o.scale.toArray(),visible:o.visible}:homePose(id)}
function extendChess(time){if(time>fx.chessDuration){fx.chessDuration=Math.ceil(time+1);syncDuration()}}
function directorSave(){saveEffects();syncDuration();base._renderKey=''}
function keyField(id,label,value,step=.1){return `<label for="${id}">${label}<input id="${id}" type="number" step="${step}" value="${Number(value).toFixed(2)}"></label>`}
function objectOptions(selected){return [...(chessEngine?.objects||[])].map(([id,o])=>`<option value="${id}" ${id===selected?'selected':''}>${o.name}</option>`).join('')}
function renderChessDirector(){const host=document.querySelector('#chessDirector');if(!host||!chessEngine||!chessMotionAPI)return;const open={};host.querySelectorAll('details').forEach(e=>open[e.id]=e.open);const tr=trackFor(motionObject),keys=[...tr.keys].sort((a,b)=>a.time-b.time);motionKey=Math.min(motionKey,keys.length-1);const k=keys[motionKey]||{time:0,...homePose(motionObject)},spec=fx.chessLogos?.[logoObject]||{type:'none',size:1,height:logoObject==='board'?.07:1.05};
 host.innerHTML=`<details id="motionKeys" ${open.motionKeys?'open':''}><summary>Piece motion · keyframes</summary><p class="sub">Times are seconds within Chess. Add poses from Edit 3D, or enter exact values below. Animated tracks override a static object pose in Video mode.</p><label for="motionObject">Animate object</label><select id="motionObject">${objectOptions(motionObject)}</select><div class="directorGrid">${keyField('sceneSecond','Scene time (s)',chessSeconds())}<button class="pill" id="seekScene">Go to time</button></div><label class="checkRow"><input id="motionEnabled" type="checkbox" ${tr.enabled!==false?'checked':''}> Enable this motion track</label><div class="directorGrid">${keyField('trackOffset','Track delay (s)',tr.offset||0)}${keyField('trackRate','Track speed ×',tr.speed||1,.05)}</div><label for="motionKey">Pose keyframe</label><select id="motionKey">${keys.map((v,i)=>`<option value="${i}" ${i===motionKey?'selected':''}>${Number(v.time).toFixed(2)}s · Pose ${i+1}${v.visible===false?' · hidden':''}</option>`).join('')}</select><div class="directorGrid">${keyField('keyTime','Key time (s)',k.time)}${keyField('keyScale','Uniform scale',k.scale?.[0]??1,.05)}${['X','Y','Z'].map((axis,i)=>keyField('keyP'+axis,'Position '+axis,k.position[i])).join('')}${['X','Y','Z'].map((axis,i)=>keyField('keyR'+axis,'Rotation '+axis+' (°)',k.rotation[i],1)).join('')}${['X','Y','Z'].map((axis,i)=>keyField('keyS'+axis,'Scale '+axis,k.scale?.[i]??1,.05)).join('')}</div><label for="keyEase">Easing into this pose</label><select id="keyEase">${['smooth','linear','in','out','hold'].map(e=>`<option ${k.ease===e?'selected':''}>${e}</option>`).join('')}</select><label class="checkRow"><input id="keyVisible" type="checkbox" ${k.visible!==false?'checked':''}> Visible at this key</label><div class="directorGrid"><button class="pill" id="previewPose">View keyframe</button><button class="pill" id="addPose">Add current 3D pose</button><button class="pill" id="duplicatePose">Duplicate key</button><button class="pill" id="deletePose">Delete key</button></div><details class="subDetails"><summary>Create a motion</summary><label for="motionPreset">Motion preset</label><select id="motionPreset"><option value="lift">Lift, spin & land</option><option value="flip">Lift, flip & land</option><option value="move">Move & turn</option><option value="capture">Capture & knock over</option></select><div class="directorGrid">${keyField('presetStart','Start (s)',chessSeconds())}${keyField('presetDuration','Duration (s)',4)}${keyField('presetHeight','Lift height',1.7)}${keyField('presetTurns','Turns',1,.25)}${keyField('presetX','Travel X',0)}${keyField('presetZ','Travel Z',-2)}</div><label for="captureTarget">Capture target</label><select id="captureTarget">${objectOptions('b-pawn-3')}</select><button class="pill wide" id="applyPreset">Replace motion from this time</button></details><button class="pill wide" id="resetMotion">Restore this object's preset motion</button></details>
 <details id="cameraKeys" ${open.cameraKeys?'open':''}><summary>Camera · orbit, side angle & close-up</summary><p class="sub">The automatic shot lowers to board level, orbits, then pushes toward the logo pieces. Custom camera keys replace that path.</p><div class="directorGrid">${[['orbitStart','Orbit starts (s)'],['orbitTime','Orbit duration (s)'],['lowerTime','Lowering duration (s)'],['orbitTurns','Orbit turns'],['lowAngle','Low camera elevation (°)'],['closeStart','Close-up starts (s)'],['closeTime','Close-up duration (s)'],['closeDistance','Close-up distance']].map(([id,label])=>keyField(id,label,fx[id])).join('')}</div><button class="pill wide" id="captureCameraKey">Add current Edit 3D camera at scene time</button><div id="cameraKeyFields"></div><button class="pill wide" id="resetCameraKeys">Restore automatic camera path</button></details>
 <details id="logoDetails" ${open.logoDetails?'open':''}><summary>Logos · piece tops & board</summary><label for="logoObject">Logo object</label><select id="logoObject">${objectOptions(logoObject)}</select><label for="logoType">Topper / logo</label><select id="logoType"><option value="none">Original piece · no logo</option><option value="stripes">Three bars · solid 3D topper</option><option value="cat">Leaping cat · solid 3D topper</option><option value="image">My image logo</option></select><button class="pill wide" id="uploadChessLogo">Upload PNG / SVG logo…</button><p class="sub">Transparent PNG or SVG works best. Uploads attach to the selected object and stay in this browser.</p><div class="directorGrid">${keyField('logoSize','Logo size',spec.size||1,.05)}${keyField('logoHeight','Topper height',spec.height??1.05,.05)}${keyField('logoX','Offset X',spec.x||0,.05)}${keyField('logoZ','Offset Z',spec.z||0,.05)}${keyField('logoYaw','Rotation Y (°)',spec.yaw||0,1)}</div><label for="logoColor">Logo tint</label><input id="logoColor" type="color" value="${spec.color||'#ffffff'}"></details>
 <details id="chessLights" ${open.chessLights?'open':''}><summary>Lighting · visible rear panel</summary><label class="checkRow"><input id="panelVisible" type="checkbox" ${fx.panelVisible!==false?'checked':''}> Show rear light panel</label><label class="checkRow"><input id="panelSafe" type="checkbox" ${fx.panelSafe!==false?'checked':''}> Keep panel behind board, facing camera</label><p class="sub">With this enabled, X is sideways offset and Z is rear distance. The camera stays on the illuminated front side.</p><label for="wallColor">Wall color</label><input id="wallColor" type="color" value="${fx.wallColor}"><label for="panelColor">Emitted light color</label><input id="panelColor" type="color" value="${fx.panelColor}"><div class="directorGrid">${[['panelPower','Emission brightness (%)'],['panelSoftness','Luminous edge softness (%)'],['panelOpacity','Luminous area opacity (%)'],['panelGlow','Panel glow (%)'],['panelGlowRadius','Glow spread (px)'],['panelX','Panel X'],['panelY','Panel height Y'],['panelZ','Panel Z'],['panelWidth','Panel width'],['panelHeight','Panel height'],['panelYaw','Panel yaw (°)'],['panelRoll','Panel roll (°)'],['coolX','Cool key X'],['coolY','Cool key Y'],['coolZ','Cool key Z'],['warmX','Warm fill X'],['warmY','Warm fill Y'],['warmZ','Warm fill Z']].map(([id,label])=>keyField(id,label,fx[id])).join('')}</div></details>`;
 host.querySelector('#motionObject').onchange=e=>{motionObject=e.target.value;motionKey=0;chessEngine.select(motionObject);renderChessDirector()};host.querySelector('#seekScene').onclick=()=>seekChess(+host.querySelector('#sceneSecond').value);
 const editKey=()=>{const track=trackFor(motionObject,true);track.keys.sort((a,b)=>a.time-b.time);return track.keys[motionKey]};host.querySelector('#motionEnabled').onchange=e=>{trackFor(motionObject,true).enabled=e.target.checked;directorSave()};for(const [id,prop]of [['trackOffset','offset'],['trackRate','speed']])host.querySelector('#'+id).oninput=e=>{trackFor(motionObject,true)[prop]=prop==='speed'?Math.max(.05,+e.target.value):+e.target.value;directorSave()};host.querySelector('#motionKey').onchange=e=>{motionKey=+e.target.value;renderChessDirector()};
 for(const axis of ['X','Y','Z']){const i=['X','Y','Z'].indexOf(axis);for(const [prefix,prop]of [['keyP','position'],['keyR','rotation'],['keyS','scale']])host.querySelector('#'+prefix+axis).oninput=e=>{editKey()[prop][i]=+e.target.value;directorSave()}}
 host.querySelector('#keyTime').onchange=e=>{const selected=editKey();selected.time=Math.max(0,+e.target.value);extendChess(selected.time);trackFor(motionObject,true).keys.sort((a,b)=>a.time-b.time);motionKey=trackFor(motionObject,true).keys.indexOf(selected);directorSave();renderChessDirector()};host.querySelector('#keyScale').oninput=e=>{editKey().scale=Array(3).fill(Math.max(.05,+e.target.value));for(const axis of ['X','Y','Z'])host.querySelector('#keyS'+axis).value=editKey().scale[0];directorSave()};host.querySelector('#keyEase').onchange=e=>{editKey().ease=e.target.value;directorSave()};host.querySelector('#keyVisible').onchange=e=>{editKey().visible=e.target.checked;directorSave()};host.querySelector('#previewPose').onclick=()=>{const tr=trackFor(motionObject);seekChess((keys[motionKey].time/(tr.speed||1))+(tr.offset||0))};
 host.querySelector('#addPose').onclick=()=>{const tr=trackFor(motionObject,true),time=chessSeconds(),key={time:(time-(tr.offset||0))*(tr.speed||1),...currentObjectPose(motionObject),ease:'smooth'};tr.keys.push(key);tr.keys.sort((a,b)=>a.time-b.time);motionKey=tr.keys.indexOf(key);directorSave();renderChessDirector()};host.querySelector('#duplicatePose').onclick=()=>{const track=trackFor(motionObject,true),key=structuredClone(editKey());key.time+=1;track.keys.push(key);track.keys.sort((a,b)=>a.time-b.time);motionKey=track.keys.indexOf(key);extendChess(key.time);directorSave();renderChessDirector()};host.querySelector('#deletePose').onclick=()=>{const tr=trackFor(motionObject,true);tr.keys.sort((a,b)=>a.time-b.time);if(tr.keys.length>1)tr.keys.splice(motionKey,1);directorSave();renderChessDirector()};host.querySelector('#resetMotion').onclick=()=>{delete fx.chessTracks[motionObject];motionKey=0;directorSave();renderChessDirector()};host.querySelector('#applyPreset').onclick=()=>applyMotionPreset(host);
 for(const id of ['orbitStart','orbitTime','lowerTime','orbitTurns','lowAngle','closeStart','closeTime','closeDistance','panelPower','panelSoftness','panelOpacity','panelGlow','panelGlowRadius','panelX','panelY','panelZ','panelWidth','panelHeight','panelYaw','panelRoll','coolX','coolY','coolZ','warmX','warmY','warmZ'])host.querySelector('#'+id).oninput=e=>{fx[id]=+e.target.value;directorSave()};host.querySelector('#panelSafe').onchange=e=>{fx.panelSafe=e.target.checked;directorSave()};host.querySelector('#panelVisible').onchange=e=>{fx.panelVisible=e.target.checked;directorSave()};host.querySelector('#wallColor').oninput=e=>{fx.wallColor=e.target.value;directorSave()};host.querySelector('#panelColor').oninput=e=>{fx.panelColor=e.target.value;directorSave()};
 host.querySelector('#captureCameraKey').onclick=()=>{if(!chessEditing)setChessMode(true);const age=chessSeconds();fx.chessCameraKeys||=[];if(!fx.chessCameraKeys.length&&age>0)for(const time of [0,Math.min(fx.chessPull,age-.1)])fx.chessCameraKeys.push({time,...chessMotionAPI.sampleCamera(time,{...fx,chessCameraKeys:[]}),ease:'smooth'});const key={time:age,...chessEngine.getCamera(),ease:'smooth'};fx.chessCameraKeys.push(key);fx.chessCameraKeys.sort((a,b)=>a.time-b.time);cameraKey=fx.chessCameraKeys.indexOf(key);directorSave();renderChessDirector()};host.querySelector('#resetCameraKeys').onclick=()=>{fx.chessCameraKeys=[];directorSave();renderChessDirector()};renderCameraKeys();
 const logoType=host.querySelector('#logoType');logoType.value=spec.type;host.querySelector('#logoObject').onchange=e=>{logoObject=e.target.value;renderChessDirector()};function logoEdit(){fx.chessLogos||={};return fx.chessLogos[logoObject]||=(structuredClone(spec))}logoType.onchange=e=>{logoEdit().type=e.target.value;directorSave()};for(const [id,prop]of [['logoSize','size'],['logoHeight','height'],['logoX','x'],['logoZ','z'],['logoYaw','yaw']])host.querySelector('#'+id).oninput=e=>{logoEdit()[prop]=+e.target.value;directorSave()};host.querySelector('#logoColor').oninput=e=>{logoEdit().color=e.target.value;directorSave()};host.querySelector('#uploadChessLogo').onclick=()=>uploadLogo(logoObject);
}
function applyMotionPreset(host){const n=id=>+host.querySelector('#'+id).value,start=Math.max(0,n('presetStart')),duration=Math.max(.1,n('presetDuration')),type=host.querySelector('#motionPreset').value,track=trackFor(motionObject,true),base=chessMotionAPI.sampleTrack(track,start,homePose(motionObject)),dest=structuredClone(base),mid=structuredClone(base),turn=n('presetTurns')*360;dest.position[0]+=n('presetX');dest.position[2]+=n('presetZ');dest.rotation[1]+=turn;mid.position=base.position.map((v,i)=>(v+dest.position[i])/2);mid.position[1]+=Math.max(0,n('presetHeight'));mid.rotation[1]+=turn/2;if(type==='flip'){mid.rotation[0]+=180;dest.rotation[0]+=360}if(type==='capture'){const targetId=host.querySelector('#captureTarget').value;if(targetId===motionObject)return;const target=trackFor(targetId,true),victim=chessMotionAPI.sampleTrack(target,start,homePose(targetId));dest.position=[...victim.position];const fall=structuredClone(victim);fall.position[0]+=1;fall.position[1]=.15;fall.rotation[2]+=90;target.keys=target.keys.filter(k=>k.time<start);target.keys.push({time:start,...victim},{time:start+duration*.8,...victim},{time:start+duration+1,...fall},{time:start+duration+1.5,...fall,visible:false});extendChess(start+duration+1.5)}track.keys=track.keys.map(k=>({...k,time:k.time/(track.speed||1)+(track.offset||0)}));track.offset=0;track.speed=1;track.enabled=true;track.keys=track.keys.filter(k=>k.time<start);track.keys.push({time:start,...base,ease:'smooth'});if(type==='lift'||type==='flip')track.keys.push({time:start+duration/2,...mid,ease:'smooth'});track.keys.push({time:start+duration,...dest,ease:'smooth'});extendChess(start+duration);motionKey=track.keys.length-1;directorSave();seekChess(start);renderChessDirector()}
function renderCameraKeys(){const host=document.querySelector('#cameraKeyFields');if(!host)return;const keys=fx.chessCameraKeys||[];if(!keys.length){host.innerHTML='<p class="sub">Automatic cinematic camera active.</p>';return}cameraKey=Math.min(cameraKey,keys.length-1);const key=keys[cameraKey];host.innerHTML=`<label for="cameraKeySelect">Camera keyframe</label><select id="cameraKeySelect">${keys.map((k,i)=>`<option value="${i}" ${i===cameraKey?'selected':''}>${k.time.toFixed(2)}s · Camera ${i+1}</option>`).join('')}</select><div class="directorGrid">${keyField('cameraKeyTime','Key time (s)',key.time)}${keyField('cameraKeyFov','Field of view (°)',key.fov||38)}${['X','Y','Z'].map((a,i)=>keyField('cameraP'+a,'Camera '+a,key.position[i])).join('')}${['X','Y','Z'].map((a,i)=>keyField('cameraT'+a,'Look at '+a,key.target[i])).join('')}</div><label for="cameraEase">Camera easing</label><select id="cameraEase">${['smooth','linear','in','out','hold'].map(e=>`<option ${key.ease===e?'selected':''}>${e}</option>`).join('')}</select><button class="pill wide" id="viewCameraKey">View camera key</button><button class="pill wide" id="deleteCameraKey">Delete camera key</button>`;host.querySelector('#cameraKeySelect').onchange=e=>{cameraKey=+e.target.value;renderCameraKeys()};for(const [prefix,prop]of [['cameraP','position'],['cameraT','target']])for(const [i,axis]of ['X','Y','Z'].entries())host.querySelector('#'+prefix+axis).oninput=e=>{key[prop][i]=+e.target.value;directorSave()};host.querySelector('#cameraKeyTime').onchange=e=>{key.time=Math.max(0,+e.target.value);extendChess(key.time);directorSave()};host.querySelector('#cameraKeyFov').oninput=e=>{key.fov=Math.max(10,Math.min(100,+e.target.value));directorSave()};host.querySelector('#cameraEase').onchange=e=>{key.ease=e.target.value;directorSave()};host.querySelector('#viewCameraKey').onclick=()=>{if(chessEditing)setChessMode(false);seekChess(key.time)};host.querySelector('#deleteCameraKey').onclick=()=>{keys.splice(cameraKey,1);directorSave();renderCameraKeys()}}
async function uploadLogo(id){const input=document.createElement('input');input.type='file';input.accept='image/png,image/jpeg,image/webp,image/svg+xml';input.hidden=true;document.body.append(input);input.onchange=async()=>{const file=input.files[0];if(!file)return;const data=await new Promise(resolve=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.readAsDataURL(file)});const image=new Image();image.onload=()=>{chessEngine.setLogoImage(id,image);fx.chessLogos||={};fx.chessLogos[id]={...(fx.chessLogos[id]||{}),type:'image',size:fx.chessLogos[id]?.size||1,height:fx.chessLogos[id]?.height??(id==='board'?.07:1.05)};directorSave();renderChessDirector()};image.src=data;await saveAsset('chess-logo-'+id,data)};input.click()}
async function restoreChessLogos(){try{const db=await assetDB(),req=db.transaction('assets').objectStore('assets').openCursor();req.onsuccess=()=>{const cursor=req.result;if(!cursor){db.close();return}if(String(cursor.key).startsWith('chess-logo-')){const id=String(cursor.key).slice(11),im=new Image();im.onload=()=>chessEngine?.setLogoImage(id,im);im.src=cursor.value}cursor.continue()}}catch{}}
const selectBeforeDirector=selectEffect;selectEffect=function(key,jump=true){selectBeforeDirector(key,jump);if(key==='chess'){const host=document.createElement('section');host.id='chessDirector';controls.querySelector('#chessEditor').after(host);renderChessDirector()}};stages.querySelectorAll('button').forEach(b=>b.onclick=()=>selectEffect(b.dataset.stage));
const original3DMode=setChessMode;setChessMode=function(edit){original3DMode(edit);renderChessDirector()};
const oldEngineChanged=chessChanged;chessChanged=function(persist=false){oldEngineChanged(persist);if(chessEngine&&!chessEngine._logosRestored){chessEngine._logosRestored=true;restoreChessLogos()}};
const cssDirector=document.createElement('style');cssDirector.textContent='#chessDirector details{border-bottom:1px solid #30333a;padding:15px 0}#chessDirector summary{cursor:pointer;font-size:13px;color:#ddd}#chessDirector .subDetails{border:0}.directorGrid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:12px 0}.directorGrid label{margin:0!important;font-size:11px}.directorGrid input{display:block;min-width:0;width:100%;background:#191c22;color:#e2e3e9;border:1px solid #3a3f48;border-radius:5px;padding:8px;margin-top:5px}#chessDirector select{width:100%}.checkRow{display:flex;align-items:center;gap:8px}.checkRow input{width:auto}';document.head.append(cssDirector);
